-- Corrige mensagem_familia dos protocolos que ficaram com o texto genérico de
-- demonstração (copiado do seed em 016) em vez de uma mensagem própria do protocolo.
-- Só atualiza linhas que ainda estão com o texto genérico original: edições feitas
-- manualmente pelo Admin do Assistente Fadelito depois do seed não são sobrescritas.

BEGIN;

UPDATE public.protocolos
SET mensagem_familia = 'Olá, [nome do responsável]. Escrevemos sobre a administração de medicamento à criança na escola. A coordenação está conferindo a autorização e a documentação necessárias antes de qualquer procedimento, seguindo o protocolo da Rede Fadelito, e nenhuma medicação é administrada sem essa validação formal. Pedimos que envie ou confirme a receita e as orientações atualizadas pelo canal institucional. Qualquer dúvida, estamos à disposição para conversar.'
WHERE titulo = 'Protocolo de administração de medicamentos'
  AND mensagem_familia IN ('Olá, [nome do responsável]. Gostaríamos de conversar sobre uma situação observada na rotina escolar. A equipe acolheu a criança, registrou os fatos objetivos e encaminhou o tema à coordenação. Estamos seguindo o protocolo da Rede Fadelito e retornaremos pelo canal institucional com os próximos passos. Permanecemos à disposição para dialogar.', 'Olá, [nome do responsável]. Estamos entrando em contato para informar uma situação relacionada a registros de imagem. Assim que o tema foi identificado, preservamos as informações e encaminhamos a verificação à direção, seguindo as regras de privacidade e acesso da escola. Estamos confirmando os fatos antes de qualquer conclusão e retornaremos pelo canal institucional com o posicionamento e os próximos passos. Ficamos à disposição para conversar.');

